def max_joke_sets(N, joke_types, hierarchy):
    def dfs(node, parent, visited, joke_set):
        visited[node] = True
        joke_set.add(joke_types[node - 1])

        for neighbor in graph[node]:
            if neighbor != parent and not visited[neighbor]:
                if not dfs(neighbor, node, visited, joke_set):
                    return False

        for neighbor in graph[node]:
            if neighbor != parent and visited[neighbor]:
                if not check_consecutive(joke_set, joke_types[neighbor - 1]):
                    return False

        return True

    def check_consecutive(current_set, new_joke):
        current_list = list(current_set)
        current_list.append(new_joke)
        current_list.sort()
        for i in range(len(current_list) - 1):
            if abs(current_list[i] - current_list[i + 1]) != 1:
                return False
        return True

    graph = defaultdict(list)
    for A, B in hierarchy:
        graph[A].append(B)

    visited = [False] * (N + 1)
    count = 0
    for i in range(1, N + 1):
        if not visited[i]:
            joke_set = set()
            if dfs(i, -1, visited, joke_set):
                count += 1

    return count

