def count_valid_sets(N: int, V: List[int], A: List[List[int]]) -> int:
    graph = [[] for _ in range(N + 1)]
    for x, y in A:
        graph[x].append(y)

    def dfs(node: int, parent: int, taken: set) -> int:
        count = 0
        for neighbor in graph[node]:
            if neighbor != parent and V[neighbor - 1] not in taken:
                new_taken = taken.copy()
                new_taken.add(V[neighbor - 1])
                if check_consecutive(new_taken):
                    count += dfs(neighbor, node, new_taken)
        return count + 1

    def check_consecutive(s: set) -> bool:
        s = sorted(list(s))
        for i in range(len(s) - 1):
            if s[i + 1] - s[i] != 1:
                return False
        return True

    return dfs(1, 0, {V[0 - 1]})

