def dfs(node, parent, graph, jokes, memo):
    if node in memo:
        return memo[node]

    joke_set = {jokes[node]}
    valid = True

    for neighbor in graph[node]:
        if neighbor != parent:
            child_joke_set, child_valid = dfs(neighbor, node, graph, jokes, memo)
            if not child_valid:
                valid = False
                break
            joke_set.update(child_joke_set)

