def dfs(employee, visited, graph, jokes, parent_jokes):
    visited.add(employee)
    current_jokes = set()

    for subordinate in graph[employee]:
        if subordinate not in visited:
            subordinate_jokes = dfs(subordinate, visited, graph, jokes, current_jokes)
            if not is_consecutive(subordinate_jokes + [jokes[subordinate]]):
                return []
            current_jokes.update(subordinate_jokes)

    current_jokes.add(jokes[employee])
    parent_jokes.update(current_jokes)

    return list(parent_jokes)

